# 1) PlayerID 기반 상태 관리 구조(GameState)

기존에는 `character` 한 명만 관리하던 것을, 멀티 플레이를 위해 `characters[UUID: CharacterState]` 형태로 확장

###  예시 코드: GameState

```swift
struct GameState {
    public private(set) var characters: [UUID: CharacterState]
    
    public let localPlayerID: UUID

    public init(
        localPlayerID: UUID,
        opponentPlayerIDs: [UUID] = [],
    ) {
        self.localPlayerID = localPlayerID
        var dict: [UUID: CharacterState] = [localPlayerID: CharacterState()]
        for id in opponentPlayerIDs where id != localPlayerID {
            dict[id] = CharacterState()
        }
        self.characters = dict
    }
    
   public mutating func setMoveX(_ moveX: Double, for id: UUID) {
        characters[id, default: .init()].moveX = moveX
    }

    public mutating func setGrounded(_ grounded: Bool, for id: UUID) {
        characters[id, default: .init()].isGrounded = grounded
    }
    ...
}
```

이렇게 하면 로컬/상대 분기 없이 id만으로 동일하게 관리 가능.


# 2) 점프/리스폰 요청도 PlayerID 기반으로 통합(GameplayManager)

플레이어별 입력(점프 요청)을 분기 처리하지 않고, `Set<UUID>` 같은 구조로 요청을 관리하도록 변경

### 예시 코드: 점프 요청

```swift
final class GameplayManager {
    private(set) var state = GameState()
    private var jumpRequests: Set<UUID> = []

    func requestJump(for id: UUID) {
        jumpRequests.insert(id)
    }

    func isJumpRequested(for id: UUID) -> Bool {
        jumpRequests.contains(id)
    }

    func resetJumpRequest(for id: UUID) {
        jumpRequests.remove(id)
    }
}
```

# 3) GameScene에서 멀티 캐릭터 컨트롤러 생성 및 관리

GameScene은 `localPlayerID` 와 `opponentPlayerIDs`를 받아서
각각 `CharacterController`를 생성하고, Dictionary로 관리

### 예시 코드: GameScene 캐릭터 생성

```swift
final class GameScene: SKScene {

    private let localPlayerID: UUID
    private let opponentPlayerIDs: [UUID]

    private var characterControllers: [UUID: CharacterController] = [:]
    private var cameraSystem: CameraSystem?

    init(
        size: CGSize,
        gameplayManager: GameplayManager,
        localPlayerID: UUID,
        opponentPlayerIDs: [UUID] = []
    ) {
        self.localPlayerID = localPlayerID
        self.opponentPlayerIDs = opponentPlayerIDs
        self.gameplayManager = gameplayManager
        super.init(size: size)
    }

    override func didMove(to view: SKView) {
        setupCharacters()
    }

    private func setupCharacters() {
        guard let cameraSystem else { return }

        // 1) 로컬 생성
        let localController = CharacterController(
            scene: self,
            cameraSystem: cameraSystem,
            playerRole: .me
        )
        localController.setupPlayer()
        characterControllers[localPlayerID] = localController

        // 2) 상대 생성
        for id in opponentPlayerIDs where id != localPlayerID {
            let opponentController = CharacterController(
                scene: self,
                cameraSystem: cameraSystem,
                playerRole: .opponent
            )
            opponentController.setupPlayer()
            characterControllers[id] = opponentController
        }

        // 카메라는 항상 로컬 플레이어 따라감
        if let localNode = characterControllers[localPlayerID]?.playerNode {
            cameraSystem.follow(localNode)
        }
    }
}
```

# 4) SpriteNode 네이밍을 PlayerID 기반으로 변경

멀티 플레이에서는 충돌 이벤트에서 “누가 충돌했는지” 추적해야 하므로 node name에 PlayerID를 심어둔다.

### 예시 코드: node 이름 변경

```swift
player.name = "\(Constants.Game.NodeName.player):\(playerID.uuidString)"
```

그리고 충돌 시 PlayerID를 추출해서 처리

### 예시 코드: playerID 추출

```swift
private func playerID(from body: SKPhysicsBody) -> UUID? {
    guard let name = body.node?.name else { return nil }
    let prefix = "\(Constants.Game.NodeName.player):"

    guard name.hasPrefix(prefix) else { return nil }
    let uuidString = String(name.dropFirst(prefix.count))
    return UUID(uuidString: uuidString)
}
```

# 5) 매 프레임 모든 플레이어 상태 반영(GameScene update)

기존에는 로컬 플레이어 1명만 업데이트 했지만, 이제는 모든 플레이어에 대해 state를 반영한다.

### 예시 코드: update 루프

```swift
override func update(_ currentTime: TimeInterval) {
    let deltaTime = currentTime - lastUpdateTime
    lastUpdateTime = currentTime

    gameplayManager.update(deltaTime: deltaTime)

    for (id, controller) in characterControllers {
        guard let cs = gameplayManager.state.characters[id] else { continue }

        controller.applyMovement(
            deltaTime: deltaTime,
            moveX: cs.moveX,
            isGrounded: cs.isGrounded
        )

        if gameplayManager.isJumpRequested(for: id) {
            controller.applyJump()
            gameplayManager.resetJumpRequest(for: id)
        }
    }
}
```

# 6) 게임 종료 조건 분리: GameEndTracker 도입

게임 종료 관련 로직(시간 종료 / 목표 도달 등)이
GameplayManager/Scene에 섞이지 않도록 `GameEndTracker`를 분리했다.

### 예시 코드: GameEndTracker

```swift
final class GameEndTracker {

    private(set) var elapsedSeconds: Int = 0
    private(set) var remainingSeconds: Int?
    private(set) var endReason: GameEndReason?

    private let limit: Int?
    private let targetPlatformIndex: Int?

    init(limit: Int? = nil, targetPlatformIndex: Int? = nil) {
        self.limit = limit
        self.targetPlatformIndex = targetPlatformIndex
        self.remainingSeconds = limit
    }

    func update(deltaTime: TimeInterval) {
        guard endReason == nil else { return }

        elapsedSeconds += Int(deltaTime)

        if let limit {
            remainingSeconds = max(limit - elapsedSeconds, 0)
            if remainingSeconds == 0 {
                endReason = .timeout
            }
        }
    }

    func updateLastLandedPlatformIndex(_ index: Int) {
        guard let targetPlatformIndex else { return }

        if index >= targetPlatformIndex {
            endReason = .reachTargetPlatform
        }
    }
}
```

